extends SceneTree

func _init():
	var scene = load("res://scenes/Player.tscn") as PackedScene
	if not scene:
		printerr("FAILED: could not load scene")
		quit(1)
	var root = scene.instantiate()
	root.process_mode = Node.PROCESS_MODE_DISABLED
	root_node.add_child(root)

	var anim = root.get_node("AnimationPlayer")
	var libs = anim.get_animation_library_list()
	var anims = []
	for lib in libs:
		anims += anim.get_animation_library(lib).get_animation_list()
	for name in ["idle", "walk_north", "walk_south", "walk_east", "walk_west", "attack"]:
		if not name in anims:
			printerr("FAILED: animation not found: ", name)
			quit(1)

	var tree = root.get_node("AnimationTree")
	var root_node = tree.tree_root
	if not root_node is AnimationNodeStateMachine:
		printerr("FAILED: tree_root is not StateMachine")
		quit(1)

	var nodes = root_node.get_node_list()
	if not "Locomotion" in nodes:
		printerr("FAILED: Locomotion node missing")
		quit(1)
	if not "Attack" in nodes:
		printerr("FAILED: Attack node missing")
		quit(1)

	var anim_attack = root_node.get_node("Attack")
	if not anim_attack is AnimationNodeAnimation:
		printerr("FAILED: Attack node not AnimationNodeAnimation")
		quit(1)
	if anim_attack.animation != &"attack":
		printerr("FAILED: Attack animation wrong: ", anim_attack.animation)
		quit(1)

	# Verify transition Locomotion->Attack has condition_attack
	var trans = root_node.get_transition_list()
	var found = false
	for i in range(root_node.get_transition_count()):
		var from = root_node.get_transition_from(i)
		var to = root_node.get_transition_to(i)
		if from == "Locomotion" and to == "Attack":
			found = true
			if root_node.get_transition(i).advance_condition != &"condition_attack":
				printerr("FAILED: Locomotion->Attack advance_condition wrong: ", root_node.get_transition(i).advance_condition)
				quit(1)
	if not found:
		printerr("FAILED: Locomotion->Attack transition missing")
		quit(1)

	print("PASS: scene structure OK")
	quit(0)

