func _ready():
	var scene = load("res://scenes/Player.tscn") as PackedScene
	var inst = scene.instantiate()
	add_child(inst)
	# Root needs to be a scene root for nodes to have valid paths during animation
	# inst is now child of this node (not root of a scene yet). SceneTree.add_child adds.
	# The inst nodes have owner set during build (to "Player"). 
	# Let's verify animation playback needs owner path resolving from scene root.
	# Actually AnimationTree.anim_player is a NodePath relative to itself, which works fine.

	var ctrl = inst.get_node("PlayerAnimController")
	var tree = inst.get_node("AnimationTree")

	ctrl.set_move_input(Vector2(1, 0))
	if tree.get("parameters/Locomotion/blend_position") != Vector2(1, 0):
		printerr("FAILED: blend_position not set: ", tree.get("parameters/Locomotion/blend_position"))
		get_tree().quit(1)

	ctrl.trigger_attack()
	# need process frames for playback.travel
	for i in range(2):
		await get_tree().process_frame
	var cur = ctrl.current_state()
	if cur != &"Attack":
		printerr("FAILED: current_state after trigger_attack is ", cur)
		get_tree().quit(1)

	# verify anim player referenced
	if tree.anim_player.is_empty():
		printerr("FAILED: anim_player not set on tree")
		get_tree().quit(1)

	print("PASS: runtime OK, state=", cur)
	get_tree().quit(0)

extends Node

func set_move_input(input_vec: Vector2) -> void:
	# Both AnimationTree and PlayerAnimController are children of the same parent (Player).
	# Relative path: get_node("../AnimationTree")
	get_node("../AnimationTree").set("parameters/Locomotion/blend_position", input_vec)

func trigger_attack() -> void:
	var tree = get_node("../AnimationTree")
	# Enable the transition condition and travel to the Attack state.
	tree.set("parameters/conditions/condition_attack", true)
	tree.get("parameters/playback").travel("Attack")
	tree.set("parameters/conditions/condition_attack", false)

func current_state() -> StringName:
	return get_node("../AnimationTree").get("parameters/playback").get_current_node()

extends Node

func _ready():
	add_to_group("test_runner")

func setup_and_test():
	var scene = load("res://scenes/Player.tscn") as PackedScene
	var inst = scene.instantiate()
	add_child(inst)
	inst.set_owner(self) # help path resolution

	var ctrl = inst.get_node("PlayerAnimController")
	var tree = inst.get_node("AnimationTree")

	# Verify anim_player was set by the build script
	if tree.anim_player.is_empty():
		printerr("FAILED: anim_player not set on tree")
		return false

	ctrl.set_move_input(Vector2(1, 0))
	if tree.get("parameters/Locomotion/blend_position") != Vector2(1, 0):
		printerr("FAILED: blend_position not set: ", tree.get("parameters/Locomotion/blend_position"))
		return false

	ctrl.trigger_attack()
	# The state machine travels; await process frames to let the animation tick.
	for i in range(2):
		await get_tree().process_frame
	var cur = ctrl.current_state()
	if cur != &"Attack":
		printerr("FAILED: current_state after trigger_attack is ", cur)
		return false

	print("PASS: runtime OK, state=", cur)
	return true

func _run():
	if await setup_and_test():
		get_tree().quit(0)
	else:
		get_tree().quit(1)
